def font(size, bold=False):
    candidates = ['C:/Windows/Fonts/timesbd.ttf' if bold else 'C:/Windows/Fonts/times.ttf',
                  'C:/Windows/Fonts/arialbd.ttf' if bold else 'C:/Windows/Fonts/arial.ttf']
    for path in candidates:
        if Path(path).exists(): return ImageFont.truetype(path, size)
    return ImageFont.load_default()

def box(draw, xy, title, body='', fill='#F7F9FC', outline='#1F4E79'):
    x1,y1,x2,y2=xy; draw.rounded_rectangle(xy, radius=14, fill=fill, outline=outline, width=3)
    draw.text((x1+12,y1+10), title, fill='#102A43', font=font(22, True))
    y=y1+43
    for line in textwrap.wrap(body, width=max(14, int((x2-x1)/10))):
        draw.text((x1+12,y), line, fill='#243B53', font=font(17)); y+=21

def arrow(draw, a, b, label=''):
    draw.line([a,b], fill='#1F4E79', width=3)
    import math
    ang=math.atan2(b[1]-a[1],b[0]-a[0]); l=12
    p1=(b[0]-l*math.cos(ang-.45),b[1]-l*math.sin(ang-.45)); p2=(b[0]-l*math.cos(ang+.45),b[1]-l*math.sin(ang+.45))
    draw.polygon([b,p1,p2], fill='#1F4E79')
    if label: draw.text(((a[0]+b[0])/2,(a[1]+b[1])/2-18),label,fill='#7A3E00',font=font(15,True))

